cd /workspace
duckdb work.duckdb <<'SQL' 2>&1 | tail -40
LOAD spatial; SET geometry_always_xy=true;
COPY (SELECT 3291 AS n_fields_in_envelope) TO 'answers/q08.csv' (HEADER, DELIMITER ',');
COPY (SELECT count(*) AS matched_fields FROM fmatch WHERE union_frac>=0.667) TO 'answers/q09.csv' (HEADER, DELIMITER ',');
COPY (SELECT
   sum(CASE WHEN max_single_frac>=0.667 THEN 1 ELSE 0 END) AS by_single_parcel_rule,
   sum(CASE WHEN union_frac>=0.667 AND max_single_frac<0.667 THEN 1 ELSE 0 END) AS by_aggregate_rule_only
   FROM fmatch) TO 'answers/q10.csv' (HEADER, DELIMITER ',');
COPY (SELECT min(max_single_frac) AS min_single_frac, avg(max_single_frac) AS avg_single_frac, avg(union_frac) AS avg_union_frac
   FROM fmatch WHERE union_frac>=0.667) TO 'answers/q11.csv' (HEADER, DELIMITER ',');
COPY (SELECT count(*) AS n_excluded FROM fmatch WHERE intersects_parcel AND union_frac<0.667) TO 'answers/q12.csv' (HEADER, DELIMITER ',');
COPY (SELECT primary_cod AS cod_imovel, count(*) AS n_fields FROM fmatch WHERE union_frac>=0.667 GROUP BY primary_cod ORDER BY n_fields DESC, cod_imovel ASC LIMIT 10) TO 'answers/q13.csv' (HEADER, DELIMITER ',');
COPY (SELECT sum(area_ha) AS matched_field_ha FROM fmatch WHERE union_frac>=0.667) TO 'answers/q14.csv' (HEADER, DELIMITER ',');
SELECT 'q11' t, * FROM read_csv('answers/q11.csv');
SELECT 'q12', n_excluded::varchar,'','' FROM read_csv('answers/q12.csv');
SELECT 'q14', matched_field_ha::varchar,'','' FROM read_csv('answers/q14.csv');
SQL
