cd /workspace
duckdb work.duckdb <<'SQL' 2>&1 | tail -40
LOAD spatial; SET geometry_always_xy=true;

-- flagged cadasters: any in-scope field with post-2020 loss>0; loss = sum of in-scope post2020 ha
CREATE OR REPLACE TABLE flagged AS
SELECT primary_cod AS cod_imovel, sum(post2020_ha) AS post2020_loss_ha
FROM mfx WHERE in_scope AND post2020_ha>0
GROUP BY primary_cod;

-- dominant class per cadaster over ALL matched fields (area-weighted, tie -> lower mb)
CREATE OR REPLACE TABLE domclass AS
SELECT cod_imovel, mb AS dominant_mb FROM (
  SELECT primary_cod AS cod_imovel, mb, sum(area_ha) AS ha,
         row_number() OVER (PARTITION BY primary_cod ORDER BY sum(area_ha) DESC, mb ASC) rn
  FROM mfx GROUP BY primary_cod, mb
) WHERE rn=1;

SELECT count(*) n_flagged, sum(post2020_loss_ha) tot FROM flagged;
SELECT d.dominant_mb, e.mb_class, e.annex1, e.in_scope, count(*) n
FROM flagged f JOIN domclass d USING(cod_imovel) LEFT JOIN eudr e ON d.dominant_mb=e.mb
GROUP BY 1,2,3,4 ORDER BY n DESC;
SQL

